// Selectors from QA screenshots (0224f4-A-talent-*, 0224f4-r2-hunter-talent-chat-locked) — heal SELECTORS only, never the expected texts.
// Changes data: creates a pending auto NDA hunter→talent (if none yet), possibly a conversation. Never sends messages.
import { test, expect } from '@playwright/test';
import path from 'path';
import { composer, waitingBar, expectComposerBlocked } from './_auto';

const CFG = {
  enabled: process.env.QA_AUTO_NDA_TALENT === '1',
  hunter: process.env.QA_AUTO_NDA_TALENT_HUNTER || 'hunter_plus',
  profile: process.env.QA_AUTO_NDA_TALENT_PROFILE || '/profile/af9b38c2-6897-43d3-8cb2-340fbf43312c',
};
const TALENT = 'טאלנט אנונימי';

test.use({ storageState: path.join(__dirname, '../../../auth', `${CFG.hunter}.json`) });

test.describe('Auto-signed standard NDA — headhunter ↔ anonymous talent (#0224f4)', () => {
  test.skip(!CFG.enabled, 'OPT-IN: QA_AUTO_NDA_TALENT=1 [QA_AUTO_NDA_TALENT_HUNTER, QA_AUTO_NDA_TALENT_PROFILE] — creates a pending NDA with a talent, see specs/hunter-nda.md 4.2');

  test('talent profile → «שליחת הודעה»: chat with «ממתינים לאישור של טאלנט אנונימי ל-NDA», composer blocked @desktop @data #0224f4', async ({ page }) => {
    test.setTimeout(120_000);
    await page.goto(CFG.profile);
    await page.getByRole('button', { name: 'שליחת הודעה' }).first().click();

    // Optional chooser dialog («פתיחת שיחה»)
    const open = page.getByRole('button', { name: 'פתיחת שיחה' });
    await Promise.race([
      open.waitFor({ timeout: 15_000 }).then(() => open.click()),
      page.waitForURL(/\/messages/, { timeout: 15_000 }),
    ]).catch(() => undefined);

    await page.waitForURL(/\/messages\?c=/, { timeout: 30_000 });
    await expect(composer(page)).toBeVisible({ timeout: 30_000 });

    const hasBar = await waitingBar(page, TALENT).waitFor({ timeout: 15_000 }).then(() => true).catch(() => false);
    if (!hasBar && (await composer(page).isEnabled())) {
      test.skip(true, 'NDA with this talent is already approved — pass another QA_AUTO_NDA_TALENT_PROFILE');
    }
    await expect(page.getByText(`ממתינים לאישור של ${TALENT} ל-NDA. אפשר לכתוב אחרי האישור.`)).toBeVisible(); // #0224f4 AC5
    await expect(page.getByText('צפייה ב-NDA')).toBeVisible();
    await expectComposerBlocked(page, 'hunter → talent waiting');
  });
});
